  1	import java.util.List;
  2	import java.util.Random;
  3	
  4	/**
  5	 * A class representing shared characteristics of animals.
  6	 *
  7	 * @version 2022/03/02
  8	 */
  9	public abstract class Animal extends Creature
 10	{
 11	    private static final Random RAND = Randomizer.getRandom();
 12	
 13	    // The amount of oxygen an animal need to survive
 14	    protected static final double ANIMAL_OXYGEN_REQUIRED = 0.0000009;
 15	
 16	    private AnimalProfile profile;
 17	    // sex of an animal, 0 = female and 1 = male
 18	    private int sex;
 19	    // If the animal is infected by disease.
 20	    private boolean isInfected;
 21	    // If the animal is immuned from the diease.
 22	    private boolean isImmuned;
 23	    // The animal's age.
 24	    private int age;
 25	    // The animal's food level.
 26	    private int foodLevel;
 27	
 28	    // Track the first step at which the animal is infected;
 29	    protected int infectionStartStep;
 30	
 31	    // total population that is die of disease.
 32	    public static int populationDieOfDisease = 0;
 33	
 34	    public Animal(boolean randomAge, Field field, Location location, AnimalProfile profile)
 35	    {
 36	        super(field, location);
 37	        this.profile = profile;
 38	        sex = RAND.nextBoolean() ? 1 : 0;
 39	        isInfected = false;
 40	        isImmuned = false;
 41	        infectionStartStep = 0;
 42	        initializeState(randomAge);
 43	    }
 44	
 45	    /**
 46	     * get the gender of an animal.
 47	     * @return sex  0 = female and 1 = male.
 48	     */
 49	    public int getSex()
 50	    {
 51	        return sex;
 52	    }
 53	
 54	    /**
 55	     * identify whether a creature need to sleep
 56	     *
 57	     * @param atDayTime true if it is at day time false if it is at night time.
 58	     * @return true if currently it is night.
 59	     */
 60	    public boolean needSleep(boolean atDayTime)
 61	    {
 62	        return !atDayTime;
 63	    }
 64	
 65	    /**
 66	     * get whether an animal is infected.
 67	     *
 68	     * @return true if an animal is infected, false otherwise.
 69	     */
 70	    public boolean getIsInfected()
 71	    {
 72	        return isInfected;
 73	    }
 74	
 75	    /**
 76	     * get if an animal is immuned.
 77	     *
 78	     * @return true if an animal is immuned, false otherwise.
 79	     */
 80	    public boolean getIsImmuned()
 81	    {
 82	        return isImmuned;
 83	    }
 84	
 85	    /**
 86	     * set an animal to be infected.
 87	     * @param isInfected infection state.
 88	     */
 89	    public void setIsInfected(boolean isInfected)
 90	    {
 91	        this.isInfected = isInfected;
 92	    }
 93	
 94	    /**
 95	     * set an animal to be immuned.
 96	     * @param isImmuned immunity state.
 97	     */
 98	    public void setIsImmuned(boolean isImmuned)
 99	    {
100	        this.isImmuned = isImmuned;
101	    }
102	
103	    protected int getAge()
104	    {
105	        return age;
106	    }
107	
108	    /**
109	     * Run one simulation step for an animal.
110	     *
111	     * @return the oxygen level the species consumed after action.
112	     */
113	    public final double act(List<Creature> newAnimals, boolean atDayTime, double oxygenLevel,
114	                            Disease disease, int step)
115	    {
116	        if(oxygenLevel < ANIMAL_OXYGEN_REQUIRED) {
117	            setDead();
118	            return 0;
119	        }
120	
121	        if(dieOfInfection(disease)) {
122	            return 0;
123	        }
124	
125	        ifCanGrantImmunity(disease, step);
126	        incrementAge();
127	        incrementHunger();
128	
129	        if(isAlive() && !needSleep(atDayTime)) {
130	            giveBirth(newAnimals);
131	            moveTo(search(disease, step));
132	        }
133	
134	        return -ANIMAL_OXYGEN_REQUIRED;
135	    }
136	
137	    /**
138	     * Make an animal infected while the disease exists.
139	     */
140	    protected void makeInfected(Disease disease, int step)
141	    {
142	        if(!getIsImmuned() && RAND.nextDouble() <= disease.INFECTION_RATE) {
143	            infect(step);
144	        }
145	    }
146	
147	    /**
148	     * give the animal immunity while condition is met.
149	     */
150	    protected void ifCanGrantImmunity(Disease disease, int step)
151	    {
152	        if(getIsInfected() && !getIsImmuned()
153	           && step - infectionStartStep >= disease.NUMBER_OF_STEP_TO_WITHSTAND) {
154	            setIsImmuned(true);
155	            setIsInfected(false);
156	        }
157	    }
158	
159	    /**
160	     * set an animal to death if it is die of infection.
161	     * Return true if an animal dies of infection
162	     */
163	    protected boolean dieOfInfection(Disease disease)
164	    {
165	        if(getIsInfected() && !getIsImmuned() && RAND.nextDouble() <= disease.MORTALITY_RATE) {
166	            setDead();
167	            populationDieOfDisease++;
168	            return true;
169	        }
170	        return false;
171	    }
172	
173	    /**
174	     * Mark the animal as infected and record the first infected step.
175	     */
176	    public void infect(int step)
177	    {
178	        setIsInfected(true);
179	        if(infectionStartStep == 0) {
180	            infectionStartStep = step;
181	        }
182	    }
183	
184	    /**
185	     * Decide whether a suitable mate is nearby.
186	     */
187	    public boolean encounterWithDiffSex()
188	    {
189	        return hasDifferentSexNearby(profile.getSpeciesClass(), profile.getMateSearchDistance());
190	    }
191	
192	    /**
193	     * Search for configured prey around the animal.
194	     */
195	    public Location search(Disease disease, int step)
196	    {
197	        return findFood(disease, step, profile.getFoodValue(), profile.getPreyTypes());
198	    }
199	
200	    /**
201	     * Increase the animal's age.
202	     */
203	    protected void incrementAge()
204	    {
205	        age++;
206	        if(age > profile.getMaxAge()) {
207	            setDead();
208	        }
209	    }
210	
211	    /**
212	     * Reduce the animal's food level.
213	     */
214	    protected void incrementHunger()
215	    {
216	        foodLevel--;
217	        if(foodLevel <= 0) {
218	            setDead();
219	        }
220	    }
221	
222	    /**
223	     * Create offspring into nearby free locations.
224	     */
225	    protected void giveBirth(List<Creature> newAnimals)
226	    {
227	        int births = breed();
228	        createAdjacentCreatures(newAnimals, births, profile::createYoung);
229	    }
230	
231	    protected boolean canBreed()
232	    {
233	        boolean reachedBreedingAge = getAge() >= profile.getBreedingAge();
234	        return reachedBreedingAge && (!profile.requiresMate() || encounterWithDiffSex());
235	    }
236	
237	    /**
238	     * Find whether there is an adjacent animal of the same species but opposite sex.
239	     */
240	    protected boolean hasDifferentSexNearby(Class<? extends Animal> species, int searchDistance)
241	    {
242	        for(Location location : getField().adjacentLocations(getLocation(), searchDistance)) {
243	            Creature nearbyCreature = getField().getCreatureAt(location);
244	            if(species.isInstance(nearbyCreature)) {
245	                Animal nearbyAnimal = species.cast(nearbyCreature);
246	                if(getSex() != nearbyAnimal.getSex()) {
247	                    return true;
248	                }
249	            }
250	        }
251	        return false;
252	    }
253	
254	    /**
255	     * Search for prey around the animal and handle infection spread during the search.
256	     */
257	    protected final Location findFood(Disease disease, int step, int foodValue,
258	                                      List<Class<? extends Creature>> preyTypes)
259	    {
260	        for(Location location : getField().adjacentLocations(getLocation(), 1)) {
261	            Creature nearbyCreature = getField().getCreatureAt(location);
262	            exposeToInfection(nearbyCreature, disease, step);
263	            if(isMatchingPrey(nearbyCreature, preyTypes) && nearbyCreature.isAlive()) {
264	                nearbyCreature.setDead();
265	                foodLevel = foodValue;
266	                return location;
267	            }
268	        }
269	        return null;
270	    }
271	
272	    private void initializeState(boolean randomAge)
273	    {
274	        if(randomAge) {
275	            age = RAND.nextInt(profile.getMaxAge());
276	            foodLevel = RAND.nextInt(profile.getFoodValue());
277	        }
278	        else {
279	            age = 0;
280	            foodLevel = profile.getFoodValue();
281	        }
282	    }
283	
284	    private void moveTo(Location preferredLocation)
285	    {
286	        Location newLocation = preferredLocation;
287	        if(newLocation == null) {
288	            newLocation = getField().freeAdjacentLocation(getLocation());
289	        }
290	
291	        if(newLocation != null) {
292	            setLocation(newLocation);
293	        }
294	        else {
295	            setDead();
296	        }
297	    }
298	
299	    private void exposeToInfection(Creature nearbyCreature, Disease disease, int step)
300	    {
301	        if(nearbyCreature instanceof Animal) {
302	            Animal nearbyAnimal = (Animal) nearbyCreature;
303	            if(nearbyAnimal.getIsInfected()) {
304	                makeInfected(disease, step);
305	            }
306	        }
307	    }
308	
309	    private boolean isMatchingPrey(Creature creature, List<Class<? extends Creature>> preyTypes)
310	    {
311	        if(creature == null) {
312	            return false;
313	        }
314	        for(Class<? extends Creature> preyType : preyTypes) {
315	            if(preyType.isInstance(creature)) {
316	                return true;
317	            }
318	        }
319	        return false;
320	    }
321	
322	    private int breed()
323	    {
324	        if(canBreed() && RAND.nextDouble() <= profile.getBreedingProbability()) {
325	            return RAND.nextInt(profile.getMaxLitterSize()) + 1;
326	        }
327	        return 0;
328	    }
329	}

